export default class MetaPolicyLayer {
  constructor(metricsEvaluator, upgradePlanner) {
    this.metricsEvaluator = metricsEvaluator;
    this.upgradePlanner = upgradePlanner;
  }

  evaluateSystemMetrics(metrics) {
    const gaps = this.metricsEvaluator.identifyGaps(metrics);
    return gaps;
  }

  prioritizeUpgrades(gaps) {
    return this.upgradePlanner.plan(gaps);
  }

  executeUpgradePlan(plan) {
    plan.forEach(upgrade => upgrade.apply());
  }
}